package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen1Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValueWithInteger() {
        Integer value = 10;
        frequency.addValue(value);
        assertEquals("Count for integer should be 1", 1L, frequency.getCount(value));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithDoubleViaComparable() {
        // Since the method casts to Comparable<?>, we test with Double
        Double value = 5.5;
        frequency.addValue(value);
        assertEquals("Count for double should be 1", 1L, frequency.getCount(value));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithString() {
        String value = "test";
        frequency.addValue(value);
        assertEquals("Count for string should be 1", 1L, frequency.getCount(value));
    }

    @Test
    public void testAddValueMultipleTimes() {
        Integer val1 = 1;
        Integer val2 = 2;
        frequency.addValue(val1);
        frequency.addValue(val1);
        frequency.addValue(val2);

        assertEquals("Count for 1 should be 2", 2L, frequency.getCount(val1));
        assertEquals("Count for 2 should be 1", 1L, frequency.getCount(val2));
        assertEquals("Total count should be 3", 3L, frequency.getSumFreq());
    }

    @Test(expected = ClassCastException.class)
    public void testAddValueWithNonComparableObject() {
        // An object that does not implement Comparable
        Object nonComparable = new Object();
        frequency.addValue(nonComparable);
    }

    @Test
    public void testAddValueWithNull() {
        // Depending on implementation, null might throw NullPointerException during cast 
        // or be stored if Comparable allows it. Based on the cast (Comparable<?>) v, 
        // if v is null, the cast succeeds but subsequent logic inside addValue(Comparable) 
        // might fail. Usually, in Apache Commons Math, adding null is not supported.
        try {
            frequency.addValue(null);
        } catch (NullPointerException | ClassCastException e) {
            // Expected behavior for many frequency implementations
        }
    }

    @Test
    public void testAddValueAndGetCumulativeStats() {
        Integer v1 = 1;
        Integer v2 = 2;
        frequency.addValue(v1);
        frequency.addValue(v2);
        frequency.addValue(v2);

        // v1 is smaller than v2
        assertEquals("Cumulative frequency for 1 should be 1", 1L, frequency.getCumFreq(v1));
        assertEquals("Cumulative frequency for 2 should be 3", 3L, frequency.getCumFreq(v2));

        assertEquals("Percentage for 1 should be 1/3", 1.0/3.0, frequency.getPct(v1), 1e-10);
        assertEquals("Cumulative percentage for 2 should be 1.0", 1.0, frequency.getCumPct(v2), 1e-10);
    }
}
